<script setup lang="ts">
import { computed, ref, watch, nextTick, onMounted, onBeforeUnmount } from 'vue';
import type { CSSProperties } from 'vue';
import './styles/theme.css'; import './styles/segmented.css';
const props = withDefaults(defineProps<{ options: (string | { label: string; value: string; disabled?: boolean })[]; modelValue?: string; defaultValue?: string; size?: 'sm' | 'md' | 'lg'; block?: boolean; disabled?: boolean; vertical?: boolean; shape?: 'default' | 'round'; label?: string }>(), { size: 'md', shape: 'default', label: '视图切换' });
const items = computed(() => props.options.map(item => typeof item === 'string' ? { label: item, value: item } : item)); const inner = ref(props.defaultValue ?? items.value.find(item => !item.disabled)?.value); const current = computed(() => props.modelValue ?? inner.value); const root = ref<HTMLElement | null>(null); const thumb = ref<CSSProperties>();
const emit = defineEmits<{ 'update:modelValue': [value: string]; change: [value: string] }>();
function select(value: string) { if (props.disabled || items.value.find(item => item.value === value)?.disabled) return; if (props.modelValue === undefined) inner.value = value; emit('update:modelValue', value); emit('change', value); }
function measure() { const target = root.value?.querySelector<HTMLElement>('[aria-checked=true]'); thumb.value = target ? { transform: `translate(${target.offsetLeft}px, ${target.offsetTop}px)`, width: `${target.offsetWidth}px`, height: `${target.offsetHeight}px` } : undefined; }
let observer: ResizeObserver | undefined; onMounted(() => { measure(); observer = new ResizeObserver(measure); if (root.value) observer.observe(root.value); }); onBeforeUnmount(() => observer?.disconnect()); watch(() => [current.value, props.size, props.vertical, props.options], async () => { await nextTick(); measure(); });
function key(event: KeyboardEvent) { if (props.disabled || !['ArrowLeft', 'ArrowRight', 'ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return; event.preventDefault(); const enabled = items.value.filter(item => !item.disabled); const at = enabled.findIndex(item => item.value === current.value); const index = event.key === 'Home' ? 0 : event.key === 'End' ? enabled.length - 1 : (at + (['ArrowRight', 'ArrowDown'].includes(event.key) ? 1 : -1) + enabled.length) % enabled.length; const next = enabled[index]; if (next) { select(next.value); root.value?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')[index]?.focus(); } }
</script>
<template><div ref="root" role="radiogroup" :aria-label="label" :aria-disabled="disabled" :class="['at-segmented', `at-segmented--${size}`, { 'at-segmented--block': block, 'at-segmented--disabled': disabled, 'at-segmented--vertical': vertical, 'at-segmented--round': shape === 'round' }]" @keydown="key"><span v-if="thumb" class="at-segmented__thumb" :style="thumb" aria-hidden="true" /><button v-for="(option, index) in items" :key="option.value" type="button" role="radio" :aria-checked="option.value === current" :tabindex="option.value === current || (!current && index === 0) ? 0 : -1" :disabled="disabled || option.disabled" :class="['at-segmented__option', { 'at-segmented__option--active': option.value === current }]" @click="select(option.value)"><slot name="option" :option="option"><span class="at-segmented__label">{{ option.label }}</span></slot></button></div></template>
